    /* SYS_SPU_SEGMENT (Cell SDK / RPCS3): 16-byte stride, big-endian.
     *   +0 type (1=COPY,2=FILL,4=INFO)  +4 ls_start  +8 size  +12 src/value */
    #define SPU_SEG_TYPE_COPY 1
    #define SPU_SEG_TYPE_FILL 2
    #define SPU_SEG_STRIDE    16u

    /* Walk the guest sys_spu_image at img_ea and copy/fill its segments into
     * the thread's local store. Returns 1 if >=1 segment landed (caller sets
     * image_loaded), else 0. Non-breaking: any empty/malformed image
     * (segs==0 / nsegs==0 / out of range) returns 0 -> legacy fallback. */
    static int spu_image_materialize(uint32_t img_ea, spu_thread_t* t)
    {
        extern uint8_t* vm_base;
        if (!img_ea || !vm_base || !t) return 0;
        uint32_t segs_ea = vm_read_be32(img_ea + 8);
        uint32_t nsegs   = vm_read_be32(img_ea + 12);
        if (segs_ea == 0 || nsegs == 0 || nsegs > 256) return 0;
        uint8_t* ls = spu_thread_get_or_alloc_ls(t);
        if (!ls) return 0;
        int copied_any = 0;
        for (uint32_t i = 0; i < nsegs; i++) {
            uint32_t base     = segs_ea + i * SPU_SEG_STRIDE;
            uint32_t type     = vm_read_be32(base + 0);
            uint32_t ls_start = vm_read_be32(base + 4);
            uint32_t size     = vm_read_be32(base + 8);
            uint32_t srcval   = vm_read_be32(base + 12);
            if (size == 0) continue;
            if (ls_start > SPU_LS_SIZE || size > SPU_LS_SIZE ||
                ls_start + size > SPU_LS_SIZE) {
                fprintf(stderr, "[SPU] image_materialize: seg %u out of range "
                        "(ls=0x%X size=0x%X), skipped\n", i, ls_start, size);
                continue;
            }
            if (type == SPU_SEG_TYPE_COPY) {
                if (srcval == 0) continue;
                memcpy(ls + ls_start, vm_base + srcval, size);
                copied_any = 1;
            } else if (type == SPU_SEG_TYPE_FILL) {
                memset(ls + ls_start, (int)(srcval & 0xFF), size);
                copied_any = 1;
            }
            /* INFO/unknown: skip. */
        }
        return copied_any;
    }

