#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* Guest main memory the real vm_read_be32 / memcpy source will use. */
static uint8_t g_mem[1 << 20];
uint8_t* vm_base = g_mem;

#ifdef TEST_USE_REAL_HELPER
/* --- Compile the REAL helper from lv2_register.c. ---
 * -Dstatic= exposes the file-statics; the stubs below satisfy the few
 * symbols spu_image_materialize transitively needs (vm_read_be32 and
 * spu_thread_get_or_alloc_ls are defined inside lv2_register.c itself).
 * lv2_register_all_syscalls + the sys_*_init externs are NOT referenced
 * by the helper, so they link only if the registration body compiles;
 * provide weak stubs. This path is the authoritative test. */
  /* See run_image_load_test.sh for the exact include/stub wiring. */
  extern int spu_image_materialize(uint32_t img_ea, void* t);
  extern uint8_t* spu_thread_get_or_alloc_ls(void* t);
  /* Minimal opaque thread carrying just a local_store pointer matching the
   * real struct's first-LS-field usage is NOT safe; instead the runner
   * compiles the real struct. main() below uses the runner-provided shim
   * make_thread()/thread_ls() declared here. */
  void*    make_thread(void);
  uint8_t* thread_ls_after(void* t); /* returns t->local_store post-call */
#else
/* --- SECONDARY: layout-pinning reimplementation (does NOT test patched code,
 *     only the offset/COPY/FILL/stride contract). --- */
  #define SPU_LS_SIZE (256*1024)
  #define SPU_SEG_TYPE_COPY 1
  #define SPU_SEG_TYPE_FILL 2
  #define SPU_SEG_STRIDE 16u
  static uint32_t vm_read_be32(uint32_t a){const uint8_t*p=g_mem+a;return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
  static int spu_image_materialize_copy(uint32_t img_ea, uint8_t* ls){
      if(!img_ea||!vm_base||!ls)return 0;
      uint32_t segs=vm_read_be32(img_ea+8),n=vm_read_be32(img_ea+12);
      if(!segs||!n||n>256)return 0; int any=0;
      for(uint32_t i=0;i<n;i++){uint32_t b=segs+i*SPU_SEG_STRIDE;
          uint32_t ty=vm_read_be32(b),ls0=vm_read_be32(b+4),sz=vm_read_be32(b+8),sv=vm_read_be32(b+12);
          if(!sz)continue; if(ls0>SPU_LS_SIZE||sz>SPU_LS_SIZE||ls0+sz>SPU_LS_SIZE)continue;
          if(ty==SPU_SEG_TYPE_COPY){if(!sv)continue;memcpy(ls+ls0,vm_base+sv,sz);any=1;}
          else if(ty==SPU_SEG_TYPE_FILL){memset(ls+ls0,(int)(sv&0xFF),sz);any=1;}}
      return any;}
#endif

static void wbe(uint32_t a,uint32_t v){uint8_t*p=g_mem+a;p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v;}

int main(void){
    int ok=1;
    uint32_t img=0x1000,segs=0x1100,data=0x2000;
    wbe(img+0,1); wbe(img+4,0x40); wbe(img+8,segs); wbe(img+12,2);
    wbe(segs+0,1);  wbe(segs+4,0x40); wbe(segs+8,16); wbe(segs+12,data);   /* COPY */
    wbe(segs+16+0,2); wbe(segs+16+4,0x80); wbe(segs+16+8,8); wbe(segs+16+12,0xAB); /* FILL */
    for(int i=0;i<16;i++) g_mem[data+i]=(uint8_t)i;

    uint8_t* ls;
    int loaded;
#ifdef TEST_USE_REAL_HELPER
    void* t = make_thread();
    loaded = spu_image_materialize(img, t);
    ls = thread_ls_after(t);
#else
    ls = (uint8_t*)calloc(1,256*1024);
    loaded = spu_image_materialize_copy(img, ls);
#endif
    if(!loaded){printf("FAIL not loaded\n");ok=0;}
    if(ls){
      for(int i=0;i<16;i++) if(ls[0x40+i]!=(uint8_t)i){printf("FAIL COPY ls[0x%X]=0x%02X\n",0x40+i,ls[0x40+i]);ok=0;break;}
      for(int i=0;i<8;i++)  if(ls[0x80+i]!=0xAB){printf("FAIL FILL ls[0x%X]=0x%02X\n",0x80+i,ls[0x80+i]);ok=0;break;}
      if(ls[0]!=0||ls[0x200]!=0){printf("FAIL untouched LS\n");ok=0;}
    } else {printf("FAIL ls null\n");ok=0;}

    /* empty/malformed -> legacy 0 */
    uint32_t bad=0x3000; wbe(bad+8,0); wbe(bad+12,0);
#ifdef TEST_USE_REAL_HELPER
    if(spu_image_materialize(bad, make_thread())!=0){printf("FAIL empty!=0\n");ok=0;}
#else
    { uint8_t* l2=(uint8_t*)calloc(1,256*1024);
      if(spu_image_materialize_copy(bad,l2)!=0){printf("FAIL empty!=0\n");ok=0;} free(l2);}
#endif
    printf(ok?"[PASS] image_load: COPY+FILL landed, flag set, empty=legacy\n":"[FAIL] image_load\n");
    return ok?0:1;
}
