# SPU image-load test. Default build runs the SECONDARY layout-pinning check
# (no runtime deps). Set REAL=1 to compile the actual lv2_register.c helper
# via -Dstatic= once the registration-body deps are stubbed in this repo.
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$HERE/../../.." && pwd)"
GCC="${1:-${GCC:-gcc}}"
if [ "${REAL:-0}" = "1" ]; then
  # Authoritative: exercise the patched static helper directly.
  "$GCC" -std=c11 -O2 -DTEST_USE_REAL_HELPER \
     -Dstatic= -I "$REPO/runtime/syscalls" -I "$REPO/include" \
     "$HERE/test_image_load_main.c" -o "$HERE/test_image_load.exe" -lm
else
  "$GCC" -std=c11 -O2 "$HERE/test_image_load_main.c" -o "$HERE/test_image_load.exe"
fi
"$HERE/test_image_load.exe"
